package cn.haiduo.orders;
import cn.haiduo.audit.Audit;
import java.util.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
public class CsvOrders {
 private final JdbcTemplate db;public CsvOrders(JdbcTemplate db){this.db=db;}
 record Line(String store,String external,UUID sku,int quantity,BigDecimal net,String currency,BigDecimal rate){}
 private ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
 public Object importOrders(UUID tenant,UUID warehouse,String csv,String actor){if(csv==null||csv.length()>100000)throw bad("CSV最多100000字符");String text=csv.strip();if(text.startsWith("\uFEFF"))text=text.substring(1);String[] lines=text.split("\\R");if(lines.length<2||lines.length>501||!lines[0].equals("store,order_no,sku,quantity,net,currency,rate"))throw bad("CSV模板无效，最多500行");if(db.queryForObject("select count(*) from warehouse where tenant_id=? and id=?",Integer.class,tenant,warehouse)!=1)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"仓库不存在");Map<String,List<Line>> groups=new LinkedHashMap<>();for(int n=1;n<lines.length;n++){String[] c=lines[n].split(",",-1);if(c.length!=7||Arrays.stream(c).anyMatch(String::isBlank)||c[0].length()>100||c[1].length()>100||!c[3].matches("[1-9][0-9]{0,5}")||!c[4].matches("[0-9]{1,12}(\\.[0-9]{1,4})?")||!c[5].matches("[A-Z]{3}")||!c[6].matches("[0-9]{1,8}(\\.[0-9]{1,8})?")||new BigDecimal(c[6]).signum()<=0)throw bad("第"+(n+1)+"行格式无效");if(c[5].equals("CNY")&&new BigDecimal(c[6]).compareTo(BigDecimal.ONE)!=0)throw bad("CNY汇率必须为1");var skus=db.query("select id from sku where tenant_id=? and code=?",(rs,i)->rs.getObject(1,UUID.class),tenant,c[2]);if(skus.isEmpty())throw bad("第"+(n+1)+"行SKU不存在");if(db.queryForObject("select count(*) from store where tenant_id=? and name=?",Integer.class,tenant,c[0])!=1)throw bad("店铺不存在或不属当前企业");Line line=new Line(c[0],c[1],skus.getFirst(),Integer.parseInt(c[3]),new BigDecimal(c[4]),c[5],new BigDecimal(c[6]));var group=groups.computeIfAbsent(c[0]+"\u0000"+c[1],k->new ArrayList<>());if(!group.isEmpty()){var first=group.getFirst();if(first.net().compareTo(line.net())!=0||!first.currency().equals(line.currency())||first.rate().compareTo(line.rate())!=0)throw bad("同订单每行须重复相同整单净收入、币种和汇率，不按行累加金额");if(group.stream().anyMatch(v->v.sku().equals(line.sku())))throw bad("同订单SKU重复，请先合并数量");}group.add(line);}
 int imported=0,duplicates=0;for(var entry:groups.entrySet().stream().sorted(Map.Entry.comparingByKey()).toList()){var group=entry.getValue();Line first=group.getFirst();UUID id=UUID.randomUUID();int added=db.update("insert into sales_order(id,tenant_id,store,external_id,net,rate,currency,rate_source,rate_at,warehouse_id) values(?,?,?,?,?,?,?,'CSV手工快照',now(),?) on conflict(tenant_id,store,external_id) do nothing",id,tenant,first.store(),first.external(),first.net(),first.rate(),first.currency(),warehouse);if(added==0){duplicates++;continue;}for(Line line:group)db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) select ?,?,?,?,cost from sku where tenant_id=? and id=?",tenant,id,line.sku(),line.quantity(),tenant,line.sku());new Audit(db).record(tenant,actor,"ORDER_IMPORT",id);imported++;}return Map.of("imported",imported,"duplicates",duplicates);}
}
